"""AI Summary, Key Takeaways, Decisions, and Action Item Models."""

import uuid
from datetime import datetime
from typing import TYPE_CHECKING, Optional
import sqlalchemy as sa
from sqlalchemy.orm import Mapped, mapped_column, relationship
from app.models.base import BaseModel

if TYPE_CHECKING:
    from app.models.recording import Recording


class Summary(BaseModel):
    """Executive summary, takeaways, and decisions generated by local Ollama LLM."""

    __tablename__ = "summaries"

    recording_id: Mapped[uuid.UUID] = mapped_column(
        sa.Uuid(as_uuid=True),
        sa.ForeignKey("recordings.id", ondelete="CASCADE"),
        nullable=False,
        index=True,
    )
    model_name: Mapped[str] = mapped_column(sa.String(64), default="llama3.2", nullable=False)
    status: Mapped[str] = mapped_column(
        sa.String(32), default="pending", index=True, nullable=False
    )  # 'pending', 'processing', 'completed', 'failed'
    prompt_version: Mapped[str] = mapped_column(sa.String(32), default="v1", nullable=False)
    summary_markdown: Mapped[str] = mapped_column(sa.Text, default="", nullable=False)
    key_takeaways: Mapped[list] = mapped_column(sa.JSON, default=list, nullable=False)
    decisions: Mapped[list] = mapped_column(sa.JSON, default=list, nullable=False)
    topics: Mapped[list] = mapped_column(sa.JSON, default=list, nullable=False)
    error_message: Mapped[Optional[str]] = mapped_column(sa.Text, nullable=True)
    completed_at: Mapped[Optional[datetime]] = mapped_column(
        sa.DateTime(timezone=True), nullable=True
    )

    # Relationships
    recording: Mapped["Recording"] = relationship("Recording", back_populates="summaries")

    def to_dict(self) -> dict:
        """Serialize summary record with ISO timestamps."""
        data = super().to_dict()
        return data


class ActionItem(BaseModel):
    """Extracted actionable tasks with assignee, due date, and timestamp links."""

    __tablename__ = "action_items"

    recording_id: Mapped[uuid.UUID] = mapped_column(
        sa.Uuid(as_uuid=True),
        sa.ForeignKey("recordings.id", ondelete="CASCADE"),
        nullable=False,
        index=True,
    )
    task: Mapped[str] = mapped_column(sa.Text, nullable=False)
    assignee: Mapped[Optional[str]] = mapped_column(sa.String(120), nullable=True)
    due_date: Mapped[Optional[str]] = mapped_column(sa.String(32), nullable=True)
    completed: Mapped[bool] = mapped_column(sa.Boolean, default=False, nullable=False)
    source_timestamp: Mapped[Optional[float]] = mapped_column(sa.Float, nullable=True)

    # Relationships
    recording: Mapped["Recording"] = relationship("Recording", back_populates="action_items")
